window.ECBA_QUESTION_BANK=window.ECBA_QUESTION_BANK||[];window.ECBA_QUESTION_BANK.push(...[{"id":"q257","domains":[8],"level":3,"tag":"Potential value and recommendation","q":"Three options satisfy the mandatory requirements. One has lower purchase cost but high operating expense; another has stronger long-term benefits but greater implementation risk. How should the analyst make a recommendation?","opts":["Select the lowest purchase cost because all options meet mandatory requirements","Compare options' potential value, including benefits, associated costs, risks, constraints, and stakeholder effects","Recommend the option with the greatest number of optional features","Wait until after implementation to compare actual value and then select a solution"],"answer":[1],"why":["Purchase price alone omits operating expense and other value considerations.","Correct. The recommendation task evaluates options and trade-offs, including benefits, costs, constraints, risks, and stakeholder value.","Feature count does not establish which option provides the greatest overall potential value.","The task recommends the most appropriate option before implementation based on potential value; actual performance can be measured later."],"ref":"Chapter 5, Analyze Potential Value and Recommend Solution, p. 47","multi":false,"sourceSet":"ecba-20-timed-practice-set-5.html"},{"id":"q258","domains":[4],"level":2,"tag":"Analyze current state","q":"A service is missing targets, but reports disagree about where delays occur. Before defining desired measures and a future process, what should the analyst do?","opts":["Define Future State by setting target measures immediately","Assess Enterprise Limitations by assuming the issue is outside the service","Define Change Strategy by comparing rollout approaches","Analyze Current State to understand existing performance, processes, and causes of the problem"],"answer":[3],"why":["Desired targets may be part of future-state work, but current performance and causes are not yet understood.","Enterprise limitations concern factors external to a solution; the reports do not establish that the cause is outside the service.","Change strategy compares transition approaches after the current and desired states are understood.","Correct. Analyzing Current State builds an understanding of the existing situation and helps identify problems and opportunities before defining change."],"ref":"Chapter 5, Analyze Current State, p. 38","multi":false,"sourceSet":"ecba-20-timed-practice-set-5.html"},{"id":"q259","domains":[8],"level":3,"tag":"Performance measures","q":"After launch, a team has collected satisfaction, processing-time, and cost data. It now compares actual results with expected outcomes and investigates why performance differs. Which task best fits this analysis?","opts":["Measure Solution Performance, to define and use relevant measures","Assess Solution Limitations, to identify factors within the solution that restrict value","Analyze Performance Measures, to interpret results and understand performance differences","Recommend Actions to Increase Solution Value, to select improvements after identifying a value gap"],"answer":[2],"why":["Measure Solution Performance defines appropriate measures and uses collected data to evaluate effectiveness; here the measures have already been collected and the results need analysis.","Solution limitations may explain findings, but they are not the task of analyzing the collected measures.","Correct. Analyze Performance Measures examines performance information to understand how the solution delivers value and why results differ.","Recommendations should follow an understanding of performance and its causes, not precede analysis of the variance."],"ref":"Chapter 5, Measure Solution Performance, p. 48; Analyze Performance Measures, p. 49","multi":false,"sourceSet":"ecba-20-timed-practice-set-5.html"},{"id":"q260","domains":[4],"level":3,"tag":"The Standard's role","q":"A candidate uses the Standard for the profession's foundational concepts and task overview, then turns to detailed sources for full guidance. Which statement best supports this study strategy?","opts":["The Standard is a concise introduction with foundational terms and 30 task examples; detailed study should also use the BABOK Guide and certification resources","The Standard provides the full knowledge-area guidance, so detailed sources are optional","The Standard is limited to a definition of business analysis and does not describe tasks","The Standard lists tasks in a mandatory sequence that should be memorized for the exam"],"answer":[0],"why":["Correct. The Standard provides a concise foundational introduction and examples of 30 tasks, while the preface directs certification candidates to the BABOK Guide and appropriate handbooks for detail.","The Standard does not provide comprehensive knowledge-area details; those are found in the BABOK Guide.","It covers much more than the definition, including mindset, competencies, approaches, organizational considerations, and tasks.","Tasks may be iterative and non-linear; the Standard is not a mandatory sequence or exam syllabus."],"ref":"Chapter 6, Summary, pp. 53–54","multi":false,"sourceSet":"ecba-20-timed-practice-set-5.html"},{"id":"q261","domains":[1],"level":1,"tag":"","q":"Which description best captures the focus of business analysis?","opts":["Understanding needs and recommending solutions that enable valuable change","Managing delivery activities so an approved solution meets time and budget targets","Defining requirements for a solution already selected by decision makers","Measuring completed solution features against the implementation plan"],"answer":[0],"why":["Correct: business analysis enables change by defining needs and recommending solutions that deliver value in context.","Delivery management is related work, but it is narrower than the defined focus of business analysis.","Business analysis investigates needs and options; it is not limited to specifying a preselected solution.","Feature conformance does not by itself define or fulfill the wider purpose of business analysis."],"ref":"The Business Analysis Standard v2.0 §2.1, printed p. 4; ECBA Exam Blueprint v1.12 p. 2, Domain 1","multi":false,"sourceSet":"ecba-20-timed-practice-set-9.html"},{"id":"q262","domains":[1],"level":1,"tag":"","q":"Why does the Standard describe business analysis as enabling change?","opts":["Because analysis replaces the need for organizational decisions","Because analysis helps define needs and identify solutions that may address them","Because analysis guarantees that every recommended change will produce benefits","Because analysis is performed only after a change has been approved"],"answer":[1],"why":["Analysis supports decisions but does not replace authorized decision making.","Correct: defining needs and recommending solutions helps an organization understand and undertake change.","Recommendations support value creation but cannot guarantee outcomes.","Business analysis can inform change before approval and continue as understanding evolves."],"ref":"The Business Analysis Standard v2.0 §2.1, printed p. 4; ECBA Exam Blueprint v1.12 p. 2, Domain 1","multi":false,"sourceSet":"ecba-20-timed-practice-set-9.html"},{"id":"q263","domains":[1],"level":1,"tag":"","q":"What does the phrase “in context” add to the definition of business analysis?","opts":["It limits analysis to the organization’s formal reporting structure","It means value is determined only after a solution is fully implemented","It recognizes that circumstances influence needs, solutions, and stakeholder value","It requires analysis to use one standard method in every organization"],"answer":[2],"why":["Context may include more than formal organizational structure.","Value can be considered before implementation and reassessed as outcomes emerge.","Correct: circumstances can influence how needs are understood, which solutions fit, and what stakeholders value.","The definition does not require one method regardless of context."],"ref":"The Business Analysis Standard v2.0 §2.1, printed p. 4; ECBA Exam Blueprint v1.12 p. 2, Domain 1","multi":false,"sourceSet":"ecba-20-timed-practice-set-9.html"},{"id":"q264","domains":[1],"level":1,"tag":"","q":"Which statement best expresses the BACCM meaning of a need?","opts":["A desired capability stated as a requirement","A stakeholder’s preferred solution","The transformation planned to achieve an objective","A problem or opportunity that may be addressed"],"answer":[3],"why":["A desired capability may describe a solution requirement rather than the underlying need.","A preference may suggest a solution but is not itself necessarily the need.","The transformation undertaken in response to a need is change.","Correct: a need is a problem or opportunity to be addressed."],"ref":"The Business Analysis Standard v2.0 §2.2, printed p. 5; ECBA Exam Blueprint v1.12 p. 2, Domain 1","multi":false,"sourceSet":"ecba-20-timed-practice-set-9.html"},{"id":"q265","domains":[1],"level":2,"tag":"","q":"Which statement about change is consistent with the BACCM?","opts":["Change is a transformation undertaken in response to a need","Change is the set of circumstances surrounding a solution","Change is the value experienced by a stakeholder","Change is the specific capability used to satisfy a need"],"answer":[0],"why":["Correct: change is the transformation undertaken in response to a need.","The circumstances surrounding change relate to context.","Value is the worth or usefulness of something to a stakeholder in context.","A specific way of satisfying one or more needs is a solution."],"ref":"The Business Analysis Standard v2.0 §2.2, printed p. 5; ECBA Exam Blueprint v1.12 p. 2, Domain 1","multi":false,"sourceSet":"ecba-20-timed-practice-set-9.html"},{"id":"q266","domains":[1],"level":2,"tag":"","q":"Which statement correctly distinguishes a solution from a need?","opts":["A solution is the organizational objective; a need is a stakeholder group","A solution is a way to satisfy needs; a need is a problem or opportunity to address","A solution is the context for change; a need is the value created","A solution is any approved requirement; a need is the completed transformation"],"answer":[1],"why":["An objective and stakeholder group are different concepts.","Correct: a need is the problem or opportunity, and a solution is a specific way to satisfy one or more needs in context.","Context and value have distinct meanings and do not define solution and need.","Requirements do not define the full meaning of solution; a completed transformation is not the definition of need."],"ref":"The Business Analysis Standard v2.0 §2.2, printed p. 5; ECBA Exam Blueprint v1.12 p. 2, Domain 1","multi":false,"sourceSet":"ecba-20-timed-practice-set-9.html"},{"id":"q267","domains":[1],"level":2,"tag":"","q":"What determines whether a group or individual is a stakeholder under the BACCM?","opts":["Whether they are named in the project organization chart","Whether they approve requirements or control funding","Whether they are involved in or affected by a change, need, or solution","Whether they directly use the implemented solution"],"answer":[2],"why":["Formal organizational membership is not required.","Approval and funding roles are not required to be a stakeholder.","Correct: involvement in or impact from the change, need, or solution establishes stakeholder relevance.","Direct use is not required; other parties can be involved or affected."],"ref":"The Business Analysis Standard v2.0 §2.2, printed p. 5; ECBA Exam Blueprint v1.12 p. 2, Domain 1","multi":false,"sourceSet":"ecba-20-timed-practice-set-9.html"},{"id":"q268","domains":[1],"level":2,"tag":"","q":"Which statement about context is most accurate?","opts":["It consists only of constraints imposed by the organization","It is the set of circumstances that influence or are influenced by a change","It is another term for the solution’s operating environment","It is limited to circumstances known before analysis begins"],"answer":[1],"why":["Context includes more than organizational constraints.","Correct: context is the set of circumstances that influence or are influenced by a change.","The operating environment may be part of context, but context is broader.","Context can be discovered and clarified during analysis."],"ref":"The Business Analysis Standard v2.0 §2.2, printed p. 5; ECBA Exam Blueprint v1.12 p. 2, Domain 1","multi":false,"sourceSet":"ecba-20-timed-practice-set-9.html"},{"id":"q269","domains":[1],"level":3,"tag":"","q":"Why should value not be treated as a fixed property of a solution?","opts":["Because value is always measured in financial terms","Because a solution has value only if all stakeholders agree","Because the value of a solution is determined by its technical characteristics","Because value is considered relative to stakeholder perspectives and context"],"answer":[3],"why":["Value may be financial or non-financial.","Stakeholders may perceive value differently; unanimous agreement is not required for analysis.","Technical characteristics alone do not determine stakeholder value.","Correct: stakeholder perspectives and context influence the worth or usefulness of outcomes."],"ref":"The Business Analysis Standard v2.0 §2.2–2.3, printed pp. 5–6; ECBA Exam Blueprint v1.12 p. 2, Domain 1","multi":false,"sourceSet":"ecba-20-timed-practice-set-9.html"},{"id":"q270","domains":[1],"level":3,"tag":"","q":"What is the BACCM’s role in the business analysis process?","opts":["It is a conceptual model for organizing analysis and examining relationships among core ideas","It is a sequence of steps that every BA must complete in order","It is a template for assigning one core concept to every requirement","It is an approval model for selecting among solution options"],"answer":[0],"why":["Correct: the BACCM helps organize business analysis thinking and consider relationships among core concepts.","It does not prescribe a universal sequence of steps.","The concepts are not a classification template for assigning one concept to each requirement.","The model supports analysis but does not prescribe governance approval."],"ref":"The Business Analysis Standard v2.0 §2.3, printed p. 6; ECBA Exam Blueprint v1.12 p. 2, Domain 1","multi":false,"sourceSet":"ecba-20-timed-practice-set-9.html"},{"id":"q271","domains":[1],"level":3,"tag":"","q":"Which use of the BACCM best supports completeness of analysis?","opts":["Selecting the most important concept and excluding concepts that seem secondary","Considering relevant concepts and checking how they influence one another","Treating each concept as an independent workstream with separate conclusions","Using the concepts only when a solution has already been selected"],"answer":[1],"why":["A single-concept focus can omit relevant effects and perspectives.","Correct: considering relevant concepts and their relationships helps reveal impacts and gaps in analysis.","Separate workstreams may obscure interactions among concepts.","The BACCM can structure understanding before solution selection."],"ref":"The Business Analysis Standard v2.0 §2.3, printed p. 6; ECBA Exam Blueprint v1.12 p. 2, Domain 1","multi":false,"sourceSet":"ecba-20-timed-practice-set-9.html"},{"id":"q272","domains":[1],"level":3,"tag":"","q":"Which statement best explains the relationship among need, change, and solution?","opts":["A need is a solution attribute; change is the context; solution is the stakeholder outcome","Need and solution are interchangeable, while change describes value","A need motivates change, and a solution is a way to satisfy one or more needs in context","Change is the need after approval, and solution is the change before approval"],"answer":[2],"why":["These descriptions confuse solution, context, and outcome.","Need and solution have distinct meanings; change and value are also separate concepts.","Correct: change responds to a need, and a solution is a specific way to satisfy needs in context.","Approval status does not redefine the BACCM concepts."],"ref":"The Business Analysis Standard v2.0 §2.2–2.3, printed pp. 5–6; ECBA Exam Blueprint v1.12 p. 2, Domain 1","multi":false,"sourceSet":"ecba-20-timed-practice-set-9.html"},{"id":"q273","domains":[1],"level":4,"tag":"","q":"Which statement about the six BACCM concepts is accurate?","opts":["They are alternative labels for the same underlying idea","They are relevant only when a formal project is established","They are independent categories that should not overlap","They provide a common vocabulary for discussing business analysis and its relationships"],"answer":[3],"why":["The concepts have distinct meanings even though they are related.","Business analysis occurs beyond formally established projects.","The concepts interact; they are not designed to exclude one another.","Correct: the BACCM provides shared concepts for understanding business analysis and relationships among them."],"ref":"The Business Analysis Standard v2.0 §2.3, printed p. 6; ECBA Exam Blueprint v1.12 p. 2, Domain 1","multi":false,"sourceSet":"ecba-20-timed-practice-set-9.html"},{"id":"q274","domains":[1],"level":4,"tag":"","q":"What is the strongest reason business analysis should begin with needs rather than solution features?","opts":["Needs clarify the problem or opportunity so possible solutions can be evaluated against intended value","Features are always too detailed to be discussed before implementation","The BACCM excludes solutions until all stakeholder requirements are approved","Needs are easier to measure than solution outcomes"],"answer":[0],"why":["Correct: understanding needs provides a basis for evaluating whether solution options can address the problem or opportunity and deliver value.","Some features may be discussed early; the issue is avoiding premature commitment before needs are understood.","The BACCM includes solutions and does not prescribe that all requirements be approved first.","Needs and outcomes vary in measurability; ease of measurement is not the main reason."],"ref":"The Business Analysis Standard v2.0 §2.4, printed p. 7; ECBA Exam Blueprint v1.12 p. 2, Domain 1","multi":false,"sourceSet":"ecba-20-timed-practice-set-9.html"},{"id":"q275","domains":[1],"level":4,"tag":"","q":"Which statement best distinguishes business analysis from solution delivery?","opts":["Business analysis is limited to approving requirements before delivery begins","Business analysis helps define needs and recommend options; delivery implements an authorized change","Business analysis begins only when delivery has exposed a defect","Business analysis determines implementation tasks but not desired outcomes"],"answer":[1],"why":["Business analysis is broader than approval and can continue during change.","Correct: analysis focuses on needs and solution recommendations, while delivery implements the chosen change.","Analysis can occur before implementation and is not limited to responding to defects.","Desired outcomes and value are central to analysis, not outside its scope."],"ref":"The Business Analysis Standard v2.0 §2.4, printed p. 7; ECBA Exam Blueprint v1.12 p. 2, Domain 1","multi":false,"sourceSet":"ecba-20-timed-practice-set-9.html"},{"id":"q276","domains":[1],"level":4,"tag":"","q":"Which practice best reflects the Standard’s emphasis on stakeholder value?","opts":["Use the sponsor’s preferred measure as the complete definition of value","Treat value as equivalent to benefits listed in the business case","Consider relevant stakeholder perspectives and the context when assessing expected outcomes","Assess value only after all outcomes can be expressed as financial results"],"answer":[2],"why":["The sponsor’s view may not represent other relevant stakeholders.","Business-case benefits can inform value but do not define it completely.","Correct: value should be considered in relation to stakeholders and the context of outcomes.","Value can be financial or non-financial and can be assessed before every outcome is fully measurable."],"ref":"The Business Analysis Standard v2.0 §2.4–2.5, printed pp. 7–8; ECBA Exam Blueprint v1.12 p. 2, Domain 1","multi":false,"sourceSet":"ecba-20-timed-practice-set-9.html"},{"id":"q277","domains":[1],"level":5,"tag":"","q":"Which statement about the outcomes of a change is most consistent with Section 2?","opts":["Delivering the planned solution is sufficient evidence that intended value was realized","Outcomes are relevant only when they can be measured immediately","Negative impacts are outside value analysis if planned benefits are achieved","Outcomes should be considered in relation to needs, stakeholders, and context"],"answer":[3],"why":["Delivery is an output and does not alone prove that intended value was realized.","Some outcomes emerge over time and may require later evaluation.","Negative impacts can affect stakeholder value even when benefits are achieved.","Correct: outcomes are understood in relation to the need, affected stakeholders, and context."],"ref":"The Business Analysis Standard v2.0 §2.5, printed pp. 7–8; ECBA Exam Blueprint v1.12 p. 2, Domain 1","multi":false,"sourceSet":"ecba-20-timed-practice-set-9.html"},{"id":"q278","domains":[1],"level":5,"tag":"","q":"Which approach best integrates the BACCM when evaluating whether a recommendation is sound?","opts":["Relate the need, proposed change, solution, stakeholders, context, and expected value","Compare solution features first, then infer the need and stakeholders they serve","Confirm the need and solution, while treating context and value as post-implementation concerns","Assess value only from the organization’s perspective, then document stakeholder effects"],"answer":[0],"why":["Correct: an integrated assessment considers the relevant core concepts and their relationships.","Inferring the need from selected features risks solution bias and may omit affected stakeholders.","Context and value inform analysis and recommendations before implementation as well as afterward.","Stakeholder perspectives and context are integral to considering value."],"ref":"The Business Analysis Standard v2.0 §2.3–2.5, printed pp. 6–8; ECBA Exam Blueprint v1.12 p. 2, Domain 1","multi":false,"sourceSet":"ecba-20-timed-practice-set-9.html"},{"id":"q279","domains":[1],"level":5,"tag":"","q":"What does it mean to evaluate value “in context” rather than in isolation?","opts":["Compare solutions only by the number of requirements they satisfy","Interpret outcomes in light of the circumstances and stakeholder perspectives that influence them","Use the same value criteria for every stakeholder and every change","Defer value judgment until the change is complete"],"answer":[1],"why":["Requirement counts alone do not establish value.","Correct: circumstances and stakeholder perspectives shape how outcomes are understood and valued.","Different contexts and stakeholders may make different criteria relevant.","Expected value can inform recommendations before a change is complete."],"ref":"The Business Analysis Standard v2.0 §2.3–2.5, printed pp. 6–8; ECBA Exam Blueprint v1.12 p. 2, Domain 1","multi":false,"sourceSet":"ecba-20-timed-practice-set-9.html"},{"id":"q280","domains":[1],"level":5,"tag":"","q":"Which statement best integrates the purpose of business analysis with the BACCM?","opts":["Business analysis selects a solution first and uses the BACCM to justify it","Business analysis turns every need into a requirement before considering stakeholders","Business analysis enables change by defining needs and recommending solutions that create stakeholder value in context; BACCM helps organize that thinking","Business analysis measures delivery outputs, while the BACCM defines project governance"],"answer":[2],"why":["Selecting first risks using the model to rationalize a predetermined answer instead of analyzing needs and value.","Requirements do not replace consideration of stakeholders, context, solutions, and value.","Correct: this connects the Standard’s definition with the BACCM’s role as a framework for analysis.","Delivery measurement and governance are narrower than these concepts and do not define the model."],"ref":"The Business Analysis Standard v2.0 §2.1–2.5, printed pp. 4–8; ECBA Exam Blueprint v1.12 p. 2, Domain 1","multi":false,"sourceSet":"ecba-20-timed-practice-set-9.html"},{"id":"q281","domains":[],"level":1,"tag":"Standard development","q":"A practitioner asks how the Standard reflects the experience of business analysis professionals around the world. Which statement best describes its development?","opts":["It was co-developed with the global community, using broad input, review cycles, and consensus","It was drafted by an IIBA committee and approved without external review","It was assembled from one region's practices and then translated for other regions","It was developed by selecting one method and standardizing it across industries"],"answer":[0],"why":["Correct. The Standard describes community co-development, input across sectors and regions, multiple reviews, and consensus-based decisions.","The Standard drew on international community input and multiple review cycles.","Its development involved professionals across regions rather than practices from only one region.","The Standard supports different approaches based on context instead of prescribing one method."],"ref":"Chapter 1, §1.2, p. 1","multi":false,"sourceSet":"ecba-20-untimed-practice-set-2.html"},{"id":"q282","domains":[7],"level":2,"tag":"Using the Standard","q":"A new stakeholder wants a clear introduction to the range of business analysis work before joining an initiative. Which use of the Standard best fits this need?","opts":["Use it as a mentoring and educational resource that gives an accessible overview","Use it as the complete task procedure and deliverable checklist for the initiative","Use it to identify the detailed techniques that must be applied in every situation","Use it to replace initiative-specific discussions about stakeholder needs"],"answer":[0],"why":["Correct. The Standard can support mentoring and education by giving stakeholders an accessible overview of business analysis work.","It provides task-level guidance but does not prescribe a complete, context-free procedure or deliverable checklist.","It introduces foundational techniques, while detailed technique guidance is available in other IIBA resources and should be selected by context.","The Standard does not replace elicitation or collaboration with stakeholders."],"ref":"Chapter 1, §1.5, p. 2","multi":false,"sourceSet":"ecba-20-untimed-practice-set-2.html"},{"id":"q283","domains":[7],"level":1,"tag":"Stakeholders","q":"A supplier has no role in building the solution but will be affected by new ordering rules. How should the business analyst treat the supplier?","opts":["As a stakeholder because it has a relationship to the change","As a stakeholder only if it approves the solution","As a requirement because it is affected by the change","As part of the solution because the new rules affect its work"],"answer":[0],"why":["Correct. A stakeholder may be an internal or external group or individual with a relationship to the change, need, or solution.","Approval authority is not required for a person or group to be a stakeholder.","A requirement is a usable representation of a need, not an affected party.","A solution is a way of satisfying a need; the supplier is an external stakeholder affected by it."],"ref":"Chapter 2, §2.1, p. 5","multi":false,"sourceSet":"ecba-20-untimed-practice-set-2.html"},{"id":"q284","domains":[4],"level":2,"tag":"Solutions","q":"A nonprofit wants to reduce missed home visits. The proposal combines route changes, revised staff procedures, and a simple scheduling tool. Which statement best fits the Standard's concept of a solution?","opts":["It is the scheduling tool that directly addresses the need","It can combine components that satisfy the need in context","It is the set of requirements describing the desired change","It is the future state that exists after the need is addressed"],"answer":[1],"why":["The tool is one possible component; the proposed procedures and route changes may also contribute to satisfying the need.","Correct. A solution is a specific way of satisfying one or more needs and may combine components.","Requirements represent needs and expectations; they are not the solution itself.","The future state describes desired conditions, while the solution is the means of satisfying the need."],"ref":"Chapter 2, §2.2, p. 5","multi":false,"sourceSet":"ecba-20-untimed-practice-set-2.html"},{"id":"q285","domains":[9],"level":2,"tag":"Context","q":"A proposed service change looked effective in one region but failed in another because of local regulations and seasonal demand. Which BACCM concept best helps explain this difference?","opts":["Context, because environmental circumstances influence the change","Need, because the regions experience different problems","Stakeholder, because different groups are affected","Value, because each region may judge outcomes differently"],"answer":[0],"why":["Correct. Context includes circumstances such as regulations, market conditions, seasons, processes, and technology that influence a change.","Different needs may exist, but the scenario points to surrounding circumstances that influence how the change works.","Stakeholders may be affected differently, but the regulations and seasonality are contextual conditions.","Value may differ by stakeholder, but the stated reason for the different result is the regional context."],"ref":"Chapter 2, §2.2, p. 6","multi":false,"sourceSet":"ecba-20-untimed-practice-set-2.html"},{"id":"q286","domains":[4],"level":3,"tag":"Needs and change","q":"A company replaces a well-used payment service. The new service changes customer behaviour and reveals that some customers can no longer use a key payment method. What does this illustrate?","opts":["A need can motivate change, but a change cannot create another need","A change can create a need by changing the value delivered by an existing solution","A solution's value is fixed once it has been implemented","A stakeholder need is unchanged by changes in the surrounding context"],"answer":[1],"why":["The BACCM describes a two-way relationship: needs can motivate changes, and changes can also create needs.","Correct. A change may reduce or increase the value delivered by an existing solution, creating new needs.","Value is assessed in context and can change as circumstances or solutions change.","Context and change can affect needs; the scenario illustrates a newly identified need after a service change."],"ref":"Chapter 2, §2.2, p. 5","multi":false,"sourceSet":"ecba-20-untimed-practice-set-2.html"},{"id":"q287","domains":[8],"level":1,"tag":"Shared values","q":"A business analyst encounters an unfamiliar customer workflow and asks open questions to learn about assumptions before suggesting changes. Which shared value most directly supports this behaviour?","opts":["Curiosity","Courage","Collaboration","Continuous improvement"],"answer":[0],"why":["Correct. Curiosity supports exploring the situation and learning before drawing conclusions.","Courage can support speaking up or challenging assumptions, but the action described is primarily inquiry and learning.","Collaboration involves working with others toward shared outcomes; here the emphasis is on asking questions to understand.","Continuous improvement focuses on ongoing refinement; the immediate behaviour is curiosity about an unfamiliar workflow."],"ref":"Chapter 3, §3.2, p. 9","multi":false,"sourceSet":"ecba-20-untimed-practice-set-2.html"},{"id":"q288","domains":[],"level":2,"tag":"Think as a customer","q":"A team has a list of internal feature requests but little information about the customer experience. What action best applies the principle “Think as a customer”?","opts":["Start with customer needs, then develop a detailed understanding to shape the emerging solution","Assess the requests against the team's delivery capacity before exploring customer needs","Examine the complete enterprise context, solution, and stakeholder relationships","Use examples of expected behaviour to agree on acceptance criteria"],"answer":[0],"why":["Correct. The principle starts with a high-level view of customer needs and develops that understanding to evolve the solution.","Feasibility is relevant, but the principle emphasizes understanding the customer before prioritizing features by internal capacity.","This reflects “See the whole,” which is related but focuses on the broader context and relationships.","Examples can build shared understanding and acceptance criteria, but the question asks how to orient the work around customer needs."],"ref":"Chapter 3, §3.3, pp. 10–11","multi":false,"sourceSet":"ecba-20-untimed-practice-set-2.html"},{"id":"q289","domains":[],"level":3,"tag":"Facilitation","q":"In a workshop, two groups talk past one another and cannot agree on the problem statement. Which foundational competency should the analyst use most directly to guide the group toward shared understanding?","opts":["Facilitation","Leadership and influencing","Problem solving","Systems thinking"],"answer":[0],"why":["Correct. Facilitation includes guiding workshops and helping groups negotiate and resolve conflict.","Leadership and influencing can help build consensus and guide stakeholders, but the immediate need is to structure and guide the workshop interaction.","Problem solving helps address issues and root causes; the group first needs help engaging constructively and reaching shared understanding.","Systems thinking looks holistically at the enterprise and relationships, not primarily at guiding a workshop discussion."],"ref":"Chapter 3, §3.4, p. 12","multi":false,"sourceSet":"ecba-20-untimed-practice-set-2.html"},{"id":"q290","domains":[7],"level":2,"tag":"Examples and shared understanding","q":"Stakeholders use different interpretations of “quick checkout.” The analyst brings sample customer orders and walks through what a successful checkout would look like. Which principle is being applied?","opts":["Get real using examples","Think as a customer","Analyze to determine what is valuable","Understand what is doable"],"answer":[0],"why":["Correct. Real examples help stakeholders build shared understanding and can inform acceptance criteria, design, and testing.","Thinking as a customer focuses on customer experience and needs; the concrete walkthrough specifically uses examples to clarify meaning.","Analyzing value involves assessing and prioritizing work; it does not describe the example-based clarification itself.","Understanding what is doable considers constraints and feasibility; the scenario resolves ambiguity through examples."],"ref":"Chapter 3, §3.3, p. 11","multi":false,"sourceSet":"ecba-20-untimed-practice-set-2.html"},{"id":"q291","domains":[],"level":1,"tag":"Hybrid approach","q":"An organization plans its regulatory reporting work predictively but develops a customer-facing feature in adaptive increments within the same initiative. Which approach is being used?","opts":["Predictive, because the initiative has a plan","Adaptive, because one part uses iterations","Hybrid, because different parts use predictive and adaptive approaches","Iterative, because all work is delivered in increments"],"answer":[2],"why":["Predictive describes one part of the work, but not the combination across the initiative.","Adaptive describes one part of the work, but not the combination across the initiative.","Correct. A hybrid approach combines predictive and adaptive work across an organization or within parts of an initiative.","The scenario uses adaptive increments for one part, but the combination with predictive work is what makes the overall approach hybrid."],"ref":"Chapter 4, §4.2.3, p. 14","multi":false,"sourceSet":"ecba-20-untimed-practice-set-2.html"},{"id":"q292","domains":[],"level":2,"tag":"Choosing an approach","q":"A well-defined initiative is heavily regulated, relatively straightforward, and can be completed sequentially. Which approach does the Standard suggest considering?","opts":["Predictive, because the work is understood and can be planned up front","Adaptive, because feedback is useful in all initiatives","Hybrid, because regulation always requires a mix of approaches","Adaptive, because sequential work should be delivered in increments"],"answer":[0],"why":["Correct. The Standard suggests predictive work where it is well-defined, regulated, straightforward, or sequential.","Feedback can be useful across approaches, but the scenario's characteristics align with predictive planning.","Regulation alone does not require a hybrid approach; the Standard says to choose based on the work's context.","The sequential nature of the work is listed among the conditions for considering a predictive approach."],"ref":"Chapter 4, §4.2, pp. 13–15","multi":false,"sourceSet":"ecba-20-untimed-practice-set-2.html"},{"id":"q293","domains":[5],"level":2,"tag":"Non-functional requirements","q":"A new booking solution must remain available during peak periods and meet a specified response time. What type of requirement best describes these conditions?","opts":["Functional solution requirements, because they affect system behaviour","Non-functional solution requirements, because they specify solution qualities or conditions","Stakeholder requirements, because users expect the service to work","Business requirements, because availability supports an organizational goal"],"answer":[1],"why":["Functional requirements describe capabilities and behaviour or information the solution manages; availability and response time are quality conditions.","Correct. Non-functional requirements specify conditions or qualities the solution must have, such as performance or availability.","Stakeholders may express the need, but the stated solution-level performance conditions are non-functional requirements.","A business goal may motivate the requirement, but the particular conditions apply to solution quality."],"ref":"Chapter 4, §4.4.2.3.2, p. 17","multi":false,"sourceSet":"ecba-20-untimed-practice-set-2.html"},{"id":"q294","domains":[],"level":3,"tag":"Security integration","q":"A team is discussing a security-sensitive service, but most participants are not security specialists. What is the business analyst's appropriate contribution?","opts":["Facilitate the right experts and stakeholders to identify risks and consider safeguards","Take ownership of the technical security design and approve its controls","Limit discussion to the security specialists to avoid conflicting input","Document the security requirements after the technical team has made its decisions"],"answer":[0],"why":["Correct. The Standard describes helping stakeholders collaborate, identify security risks, consider safety measures, and make informed decisions.","The analyst need not be a subject matter expert and should help the appropriate specialists and stakeholders work together.","The Standard emphasizes broad understanding and collaboration across technical and non-technical backgrounds.","Business analysis can help align security initiatives with objectives and involve stakeholders during analysis, not only document decisions afterward."],"ref":"Chapter 4, §4.5.1, p. 18","multi":false,"sourceSet":"ecba-20-untimed-practice-set-2.html"},{"id":"q295","domains":[4],"level":3,"tag":"Sustainability","q":"A product team evaluates a packaging change that lowers costs today but uses materials that may harm future resource availability. Which consideration best reflects the Standard's sustainability guidance?","opts":["Balance current needs with conserving resources for future generations and consider social and economic viability","Choose the option with the highest immediate financial return, then reassess sustainability later","Assess environmental effects alone because social and economic issues are outside sustainability","Defer sustainability analysis until the solution has been implemented"],"answer":[0],"why":["Correct. The Standard describes meeting current needs while conserving resources for future generations and considering social equity, health, and economic viability.","Sustainability is considered as part of strategy and decision-making, not only after selecting an option on immediate return.","The Standard includes environmental responsibility as well as social equity and economic viability.","The Standard encourages integrating sustainability considerations into planning and decision-making."],"ref":"Chapter 4, §4.5.4, p. 19","multi":false,"sourceSet":"ecba-20-untimed-practice-set-2.html"},{"id":"q296","domains":[7],"level":1,"tag":"Stakeholder engagement","q":"A new initiative affects customers, operational staff, and regulators. The analyst needs to identify who to involve, how they may be affected, and how to collaborate with them. Which task is the best fit?","opts":["Plan Stakeholder Engagement, to define the stakeholder list, roles, impacts, and collaboration approach","Manage Stakeholder Collaboration, to address day-to-day communication and teamwork","Plan Business Analysis Approach, to define the overall methods and activities","Prepare for Elicitation, to set up a particular information-gathering session"],"answer":[0],"why":["Correct. This task identifies relevant stakeholders, roles and characteristics, potential impacts, and collaboration and communication approaches.","Managing collaboration supports ongoing stakeholder relationships, but the scenario calls for establishing the engagement approach.","The business analysis approach covers how the analysis work will be performed overall, not the specific stakeholder engagement plan.","Preparing for elicitation plans a specific activity rather than the overall stakeholder engagement approach."],"ref":"Chapter 5, Plan Stakeholder Engagement, p. 24","multi":false,"sourceSet":"ecba-20-untimed-practice-set-2.html"},{"id":"q297","domains":[7],"level":2,"tag":"Elicitation preparation","q":"Before a requirements workshop, the analyst must select techniques, prepare materials, plan logistics, and ensure participants understand the activity. Which task should be performed?","opts":["Prepare for Elicitation, to plan the activity, participants, materials, and logistics","Conduct Elicitation, to gather and explore information during the workshop","Confirm Elicitation Results, to check the accuracy of information already gathered","Plan Stakeholder Engagement, to establish the broader approach to working with stakeholders"],"answer":[0],"why":["Correct. Prepare for Elicitation defines activity scope and outcomes, selects techniques, and plans logistics, materials, and participants.","Conduct Elicitation is the actual gathering of information; the question describes preparation beforehand.","Confirming results checks accuracy after information has been elicited.","Stakeholder engagement planning is broader; the task described is preparation for a specific elicitation activity."],"ref":"Chapter 5, Prepare for Elicitation, p. 28","multi":false,"sourceSet":"ecba-20-untimed-practice-set-2.html"},{"id":"q298","domains":[5],"level":3,"tag":"Design options","q":"A sponsor wants the analyst to choose a software vendor before other ways to address the need are discussed. What is the best next step?","opts":["Define and compare ways to satisfy the need, including build, buy, or combined options","Analyze potential value and recommend the vendor already preferred by the sponsor","Define the future state by selecting the system capabilities to procure","Specify and model detailed requirements for the proposed vendor solution"],"answer":[0],"why":["Correct. Define Design Options identifies and describes different ways to meet the need; options can include creating, purchasing, or a combination.","Analyzing value and recommending a solution follows defined options; a preference should not preclude examining alternatives.","Future state defines desired conditions and objectives, not the procurement option itself.","Detailed specification for a single vendor is premature before options are explored; the Standard cautions against choosing a design too early."],"ref":"Chapter 5, Define Design Options, p. 46","multi":false,"sourceSet":"ecba-20-untimed-practice-set-2.html"},{"id":"q299","domains":[6,8],"level":2,"tag":"Solution performance","q":"After launch, leaders want to know whether a new service is meeting its goals for satisfaction, processing time, and financial results. Which task best supports this evaluation?","opts":["Measure Solution Performance, to define measures and evaluate solution effectiveness and value","Analyze Performance Measures, to interpret performance data and identify trends","Assess Solution Limitations, to determine what is restricting value from within the solution","Recommend Actions to Increase Solution Value, to propose responses to a value gap"],"answer":[0],"why":["Correct. This task defines and uses measures to evaluate solution effectiveness and value, including stakeholder, process, and financial measures.","Analyzing performance measures interprets measurements; this scenario first asks which task establishes and uses measures to evaluate solution performance.","Assessing solution limitations looks for factors within a solution that restrict value, rather than measuring the stated outcomes.","Recommendations may follow analysis of performance and limitations; the immediate task is measuring effectiveness against goals."],"ref":"Chapter 5, Measure Solution Performance, p. 48","multi":false,"sourceSet":"ecba-20-untimed-practice-set-2.html"},{"id":"q300","domains":[],"level":3,"tag":"Summary","q":"A practitioner asks how the Standard relates to future IIBA resources. Which statement matches the closing summary?","opts":["It offers a simplified view of foundational concepts and helps shape future standards and resources","It provides an exhaustive reference that removes the need for more detailed resources","It defines a fixed lifecycle that future IIBA guidance must follow","It focuses on the BABOK Guide's knowledge areas and excludes task-level guidance"],"answer":[0],"why":["Correct. The closing summary describes an accessible view of foundational concepts and says the Standard shapes future standards and resources.","The Standard is a foundation and gateway to more detailed IIBA resources, not an exhaustive substitute.","The Standard does not prescribe one lifecycle; approaches and tasks are applied according to context.","The Standard provides task-level guidance and does not replace detailed knowledge area treatment in the BABOK Guide."],"ref":"Chapter 6, Summary, p. 54","multi":false,"sourceSet":"ecba-20-untimed-practice-set-2.html"},{"id":"q301","domains":[4],"level":1,"tag":"Standard revision","q":"A colleague asks what the 2025 revision added or expanded. Which answer best matches the Standard's summary of changes?","opts":["It expanded outcomes and value and added or revised organizational considerations","It replaced the six knowledge areas and 30 task descriptions with a new framework","It removed the BABOK Guide alignment to create an independent certification standard","It introduced one required lifecycle for every business analysis initiative"],"answer":[0],"why":["Correct. The revision expanded outcomes and value and added or revised organizational considerations, among other refinements.","The preface says the six knowledge areas and 30 task descriptions were not changed.","The revision strengthened alignment with the BABOK Guide; it did not replace that guidance or create a certification standard.","The Standard recognizes that approaches should be selected and applied in context rather than requiring one lifecycle."],"ref":"Chapter 1, §1.4, p. 2","multi":false,"sourceSet":"ecba-20-untimed-practice-set-3.html"},{"id":"q302","domains":[5],"level":2,"tag":"IIBA resources","q":"An analyst wants guidance on interpreting data to inform business decisions. Which resource in the IIBA collection is most directly aligned with that need?","opts":["The Guide to Business Data Analytics","The Agile Extension to the BABOK Guide","The Guide to Product Ownership Analysis","The Business Analysis Competency Model"],"answer":[0],"why":["Correct. The Guide to Business Data Analytics focuses on generating insights for informed decision-making.","The Agile Extension focuses on applying effective agile business analysis to generate business and customer value.","The Product Ownership Analysis guide focuses on creating and delivering products and services.","The Competency Model supports developing and understanding business analysis competencies, not data analytics guidance specifically."],"ref":"Chapter 1, §1.7, p. 3","multi":false,"sourceSet":"ecba-20-untimed-practice-set-3.html"},{"id":"q303","domains":[5],"level":1,"tag":"Needs","q":"A hospital reports that appointment no-shows have increased and wants to explore why. In the Standard's terminology, what is the need?","opts":["The problem or opportunity to be addressed","The appointment reminder application the hospital might purchase","The transformation made after selecting a solution","The value expected by one stakeholder group"],"answer":[0],"why":["Correct. A need is a problem or opportunity to be addressed.","An application is a potential solution: a way to satisfy the need.","Change is the transformation in response to a need, not the need itself.","Value is worth, importance, or usefulness to a stakeholder within a context."],"ref":"Chapter 2, §2.1, p. 5","multi":false,"sourceSet":"ecba-20-untimed-practice-set-3.html"},{"id":"q304","domains":[7],"level":2,"tag":"Stakeholder characteristics","q":"The analyst is deciding which external groups need early engagement in a proposed change. Which set of characteristics does the Standard identify as useful when considering stakeholders?","opts":["Their interest in, impact from, and influence over the change","Their job title, seniority, and location only","Their approval authority, budget ownership, and team size","Their level of technical expertise, availability, and preferred tool"],"answer":[0],"why":["Correct. Stakeholders are often defined or grouped by their interest, impact, and influence in relation to the change.","These details may help characterize stakeholders but are not the set identified in the Standard.","Formal authority and resources can matter, but stakeholder relationships are broader than these factors.","Expertise and availability can help plan activities; they do not define stakeholder relationships to the change."],"ref":"Chapter 2, §2.2, p. 5","multi":false,"sourceSet":"ecba-20-untimed-practice-set-3.html"},{"id":"q305","domains":[8],"level":2,"tag":"Value","q":"A proposed change will not increase revenue, but it may reduce expected financial losses and operational risk. How can this benefit be understood using the Standard's concept of value?","opts":["Value can be preserved by mitigating losses, risks, and costs","Value exists only when a new gain can be measured","Risk reduction is a constraint, not a form of value","Value can be recognized only after the solution is implemented"],"answer":[0],"why":["Correct. The Standard describes value as something realized through gains or preserved by mitigating losses, risks, and costs.","Value is not limited to new gains; preserving value also matters.","Risk reduction can preserve value and is not excluded from value considerations.","Potential value can be assessed before implementation to inform decisions among options."],"ref":"Chapter 2, §2.2, p. 5","multi":false,"sourceSet":"ecba-20-untimed-practice-set-3.html"},{"id":"q306","domains":[],"level":3,"tag":"BACCM","q":"A reviewer wants to use the BACCM to assess whether an analysis has overlooked important relationships among concepts. Which use of the model is most appropriate?","opts":["Evaluate relationships among the six concepts and consider the quality and completeness of the work","Select the project lifecycle based on the dominant concept","Replace stakeholder analysis with a single model diagram","Confirm that every requirement has an approved design"],"answer":[0],"why":["Correct. The BACCM is a thinking and organizing model that helps evaluate concept relationships and the quality and completeness of analysis.","The model does not select a lifecycle; approaches depend on the initiative's context.","It provides a common language and way to think, but does not replace stakeholder analysis.","The BACCM does not serve as an approval or traceability checklist for every requirement and design."],"ref":"Chapter 2, §2.3, p. 6","multi":false,"sourceSet":"ecba-20-untimed-practice-set-3.html"},{"id":"q307","domains":[8],"level":1,"tag":"Analyze for value","q":"A backlog contains many requested features, but the team has capacity for only a few. Which principle calls for continuously assessing and prioritizing work to maximize the value delivered?","opts":["Analyze to determine what is valuable","See the whole","Get real using examples","Understand what is doable"],"answer":[0],"why":["Correct. This principle emphasizes continuously assessing and prioritizing work to maximize value.","Seeing the whole means understanding the broader context, solution, and stakeholders.","Getting real using examples builds shared understanding through concrete examples.","Understanding what is doable considers constraints and feasibility; prioritization specifically for value is the focus here."],"ref":"Chapter 3, §3.3, p. 11","multi":false,"sourceSet":"ecba-20-untimed-practice-set-3.html"},{"id":"q308","domains":[7],"level":2,"tag":"Avoid waste","q":"A team continues producing status reports that no stakeholder uses and that do not support a decision or deliverable. Which principle most directly suggests removing this activity?","opts":["Avoid waste","Stimulate collaboration and continuous improvement","Analyze to determine what is valuable","Understand what is doable"],"answer":[0],"why":["Correct. Avoid waste means identifying activities that do not contribute to satisfying the need and removing them.","Continuous improvement is relevant to improving work, but the direct principle is eliminating activity that adds no value.","Value analysis helps assess work, but the principle here specifically concerns removing non-contributing activity.","Understanding what is doable focuses on constraints and feasible solutions rather than unnecessary work."],"ref":"Chapter 3, §3.3, p. 11","multi":false,"sourceSet":"ecba-20-untimed-practice-set-3.html"},{"id":"q309","domains":[2],"level":3,"tag":"Adaptability","q":"A stakeholder reacts negatively to a proposed workshop format. The analyst changes their facilitation style to help that stakeholder participate effectively. Which foundational competency is most directly demonstrated?","opts":["Adaptability","Facilitation","Leadership and influencing","Systems thinking"],"answer":[0],"why":["Correct. Adaptability includes adjusting behavioural style to increase effectiveness.","Facilitation includes guiding workshops, but the defining behaviour in this scenario is changing one's style in response to the stakeholder.","Leadership and influencing involves building consensus and guiding stakeholders toward value; it is not the specific adjustment described.","Systems thinking considers the enterprise and context holistically, not an individual's behavioural adjustment."],"ref":"Chapter 3, §3.4, p. 12","multi":false,"sourceSet":"ecba-20-untimed-practice-set-3.html"},{"id":"q310","domains":[4],"level":2,"tag":"Problem solving","q":"A proposed improvement treats a recurring service delay, but the analyst investigates its root cause to ensure the change addresses why delays occur. Which competency most directly supports this work?","opts":["Problem solving","Systems thinking","Leadership and influencing","Facilitation"],"answer":[0],"why":["Correct. The Standard connects problem solving with ensuring created value addresses the root cause of problems.","Systems thinking helps understand the enterprise holistically; the stated focus is uncovering the root cause of a specific problem.","Leadership and influencing supports recommendations and consensus, but root-cause analysis is the focus.","Facilitation supports group work, but it is not the competency most directly associated with addressing root causes."],"ref":"Chapter 3, §3.4, p. 12","multi":false,"sourceSet":"ecba-20-untimed-practice-set-3.html"},{"id":"q311","domains":[],"level":1,"tag":"Foundational techniques","q":"A team maps how work moves through an operation, then examines bottlenecks and opportunities to improve effectiveness. Which foundational technique best fits?","opts":["Process analysis","Customer journey mapping","Data storytelling","Backlog management"],"answer":[0],"why":["Correct. Process analysis examines efficiency and effectiveness and identifies opportunities for greater value.","Customer journey mapping focuses on the end-to-end customer experience and motivations when interacting with a solution.","Data storytelling communicates business context or insights from data through a narrative.","Backlog management records, tracks, and prioritizes remaining work items."],"ref":"Chapter 4, §4.3, p. 15","multi":false,"sourceSet":"ecba-20-untimed-practice-set-3.html"},{"id":"q312","domains":[5],"level":2,"tag":"Requirements and designs","q":"While sketching a proposed service screen, the team learns that users need an additional piece of information. What does the Standard suggest about the relationship between requirements and designs?","opts":["They are interdependent and cyclical; a design can reveal insights that refine requirements","They are separate deliverables and should not influence one another","Requirements must be finalized before any design activity begins","Designs replace requirements once a prototype exists"],"answer":[0],"why":["Correct. The Standard describes requirements and designs as interdependent and cyclical; design work can reveal insights that enhance requirements.","The Standard says they are interdependent, even though they serve different purposes.","Design exploration can help reveal needs, so the Standard does not require requirements to be fully finalized first.","A design represents a solution; it does not replace the usable representation of the underlying need."],"ref":"Chapter 4, §4.4.1, p. 16","multi":false,"sourceSet":"ecba-20-untimed-practice-set-3.html"},{"id":"q313","domains":[2],"level":3,"tag":"Ethical analysis","q":"An automated decision option appears efficient but may treat some stakeholders unfairly. What should the business analyst do in line with the Standard's ethical guidance?","opts":["Consider whether stakeholder needs are ethically met while assessing the value of the option","Recommend the option with the highest efficiency and address ethics after launch","Delegate ethical responsibility entirely to the solution vendor","Exclude affected stakeholders because the decision is automated"],"answer":[0],"why":["Correct. Ethical analysis considers whether stakeholder needs are ethically met alongside the value to be discovered, and aligns work with IIBA's ethical guidance.","The Standard calls for considering ethical needs during analysis, not only after implementation.","The business analysis professional retains responsibility for ethical conduct in the work; vendors do not remove that responsibility.","Automation does not remove the need to consider affected stakeholders and their needs."],"ref":"Chapter 4, §4.5.2, p. 18","multi":false,"sourceSet":"ecba-20-untimed-practice-set-3.html"},{"id":"q314","domains":[],"level":2,"tag":"Business analysis service delivery","q":"An organization has a central business analysis centre of excellence and also has analysts embedded in business units. How does the Standard view these delivery arrangements?","opts":["Organizations may combine service delivery forms to fit their context","A centre of excellence must replace all embedded analysts","Business analysis must be outsourced to a specialist provider","Each organization should select exactly one delivery form"],"answer":[0],"why":["Correct. The Standard describes several ways to deliver business analysis services and says organizations may combine them.","A centre of excellence is one possible form; the Standard does not require it to replace other arrangements.","Business Analysis as a Service is one option, but outsourcing is not required.","Organizations may combine arrangements such as a CoE, CoP, BAaS, and functions dispersed across business units."],"ref":"Chapter 4, §4.6, p. 20","multi":false,"sourceSet":"ecba-20-untimed-practice-set-3.html"},{"id":"q315","domains":[5],"level":1,"tag":"Plan business analysis approach","q":"An initiative has strict regulatory needs, an experienced team, and an uncertain solution path. The analyst is deciding how analysis work should be performed. Which task should guide this planning?","opts":["Plan Business Analysis Approach","Plan Stakeholder Engagement","Plan Business Analysis Governance","Plan Business Analysis Information Management"],"answer":[0],"why":["Correct. This task plans the overall approach for performing business analysis work, tailored to the initiative and its context.","Stakeholder engagement planning focuses on relationships, roles, and collaboration with stakeholders.","Governance planning addresses how decisions and approvals for business analysis work will be made.","Information management planning addresses how business analysis information will be stored, organized, and accessed."],"ref":"Chapter 5, Plan Business Analysis Approach, p. 23","multi":false,"sourceSet":"ecba-20-untimed-practice-set-3.html"},{"id":"q316","domains":[7],"level":2,"tag":"Stakeholder collaboration","q":"Stakeholders have agreed to participate, but they now need support to work together, address disagreements, and stay engaged toward shared outcomes. Which task is most directly relevant?","opts":["Manage Stakeholder Collaboration","Plan Stakeholder Engagement","Communicate Business Analysis Information","Conduct Elicitation"],"answer":[0],"why":["Correct. This task supports ongoing collaboration and working relationships among stakeholders toward the change's objectives.","Planning stakeholder engagement defines the approach and identifies stakeholders; the scenario concerns maintaining collaboration during the work.","Communication shares information, but does not by itself address the broader ongoing collaboration described.","Elicitation gathers information; collaboration may support it but is broader than a single elicitation activity."],"ref":"Chapter 5, Manage Stakeholder Collaboration, p. 32","multi":false,"sourceSet":"ecba-20-untimed-practice-set-3.html"},{"id":"q317","domains":[4],"level":3,"tag":"Prioritization","q":"A team must choose which requirements to address first. Several are valuable, but some have dependencies and different levels of urgency and risk. What should the analyst do?","opts":["Prioritize requirements and designs using relevant factors such as value, urgency, risk, and dependencies","Approve all requirements in the order stakeholders submitted them","Trace requirements to solution components and use trace order as priority","Validate every requirement and then treat them as equally important"],"answer":[0],"why":["Correct. Prioritization ranks requirements and designs using factors relevant to the context, including value, urgency, risk, and dependencies.","Submission order does not establish relative value or urgency, and approval is a separate task.","Traceability shows relationships and lineage; it does not by itself determine priority.","Validation checks alignment with goals and value, but validated requirements can still have different priorities."],"ref":"Chapter 5, Prioritize Requirements and Designs, p. 35","multi":false,"sourceSet":"ecba-20-untimed-practice-set-3.html"},{"id":"q318","domains":[7],"level":2,"tag":"Assessing changes","q":"A stakeholder requests a change to an approved design after a linked requirement is modified. Before updating the design, what should the analyst do?","opts":["Assess the proposed change's impact on value, scope, and related requirements and designs","Apply the change immediately because the original requirement changed","Reprioritize every requirement without examining the requested change","Revalidate the entire solution without assessing the change's consequences"],"answer":[0],"why":["Correct. Assess Requirement and Design Changes evaluates the consequences of a proposed change so stakeholders can make an informed decision.","A related requirement change does not automatically mean every design change should be applied without impact analysis.","Prioritization may need to be revisited, but first assess the specific change and its effects.","Validation may be appropriate after changes, but it does not replace assessing the change's impact before deciding how to proceed."],"ref":"Chapter 5, Assess Requirement and Design Changes, p. 36","multi":false,"sourceSet":"ecba-20-untimed-practice-set-3.html"},{"id":"q319","domains":[4],"level":3,"tag":"Current state","q":"Before proposing a new operating model, the analyst studies current capabilities, processes, and performance to understand why the business need exists. Which task is being performed?","opts":["Analyze Current State","Define Future State","Assess Enterprise Limitations","Define Change Strategy"],"answer":[0],"why":["Correct. Analyze Current State helps understand the existing situation, including relevant capabilities, performance, problems, and opportunities.","Define Future State establishes desired conditions and objectives, which are informed by understanding the current state.","Assess Enterprise Limitations investigates factors restricting value, often in relation to a solution; this scenario is broader current-state analysis.","Define Change Strategy compares approaches for moving from current to future state, after those states and options are understood."],"ref":"Chapter 5, Analyze Current State, p. 38","multi":false,"sourceSet":"ecba-20-untimed-practice-set-3.html"},{"id":"q320","domains":[],"level":3,"tag":"Summary","q":"A colleague believes business analysis is limited to project delivery roles. Which point from the Standard's summary best corrects this assumption?","opts":["Business analysis can support strategic, initiative, and delivery levels and a variety of career paths","Business analysis is a specialized role used only during project implementation","Business analysis applies only to requirements and design documentation","Business analysis is relevant only to professionals with a business analyst job title"],"answer":[0],"why":["Correct. The summary describes business analysis at strategic, initiative, and delivery levels and notes that the skills support varied career paths.","The Standard presents business analysis as applicable beyond implementation and across many organizational activities.","The Standard covers foundational concepts, mindset, competencies, techniques, and a broad set of tasks, not only documentation.","The Standard says business analysis can be performed by people across roles, not only those with a specific title."],"ref":"Chapter 6, Summary, p. 53","multi":false,"sourceSet":"ecba-20-untimed-practice-set-3.html"},{"id":"q321","domains":[],"level":1,"tag":"Using the Standard","q":"A business analyst is beginning work in a new organization and wants a reliable starting point for understanding accepted business analysis practices. How should the analyst use the Standard?","opts":["As a foundation of concepts and proven practices, applied to the initiative’s context","As a mandatory process that must be followed identically in every organization","As a substitute for understanding the business need","As a detailed specification for every solution design"],"answer":[0],"why":["Correct. The Standard summarizes foundational concepts and proven practices, and says guidance should be applied with the context and need of each initiative in mind.","The Standard is guidance; it explicitly says it should be applied with consideration for the specific context and need.","The business need still must be understood; the Standard supports analysis rather than replacing it.","It is a foundation and overview, not a complete detailed specification for every solution."],"ref":"Chapter 1, §1.1, p. 1","multi":false,"sourceSet":"ecba-20-untimed-practice.html"},{"id":"q322","domains":[5],"level":2,"tag":"Using the Standard","q":"A colleague needs detailed task guidance and examples for exam study. What is the best way to use the Standard alongside other IIBA resources?","opts":["Treat the Standard as the only study source because it contains the full task guidance","Use the Standard as an overview and gateway, then consult the BABOK Guide and relevant detailed resources","Skip the Standard and use only a technique list","Use the Standard only to select a software development method"],"answer":[1],"why":["The Standard is a simplified overview; its preface directs certification candidates to the BABOK Guide and appropriate handbooks for detail.","Correct. The Standard is an accessible foundation and gateway to detailed sources, including the BABOK Guide.","The Standard covers much more than techniques, including concepts, mindset, approaches, organizational considerations, and tasks.","It is broader than software development and applies across contexts and types of initiatives."],"ref":"Chapter 1, §§1.5–1.7, pp. 2–3","multi":false,"sourceSet":"ecba-20-untimed-practice.html"},{"id":"q323","domains":[],"level":1,"tag":"Business analysis definition","q":"A department reports frequent invoice errors and asks for a new finance application. What should the business analyst focus on first, consistent with the definition of business analysis?","opts":["Define the need and understand the problem or opportunity before recommending a solution","Choose the application with the largest feature set","Write a detailed design for the new application","Begin training users on a proposed system"],"answer":[0],"why":["Correct. Business analysis enables change by defining needs and recommending solutions that deliver value in context.","Selecting a product before defining the need risks solving the wrong problem.","Design details should follow an understanding of the need and suitable solution options.","Training may support a transition later, but it does not establish what need must be addressed."],"ref":"Chapter 2, §2.1, p. 5","multi":false,"sourceSet":"ecba-20-untimed-practice.html"},{"id":"q324","domains":[4],"level":2,"tag":"BACCM","q":"A team uses the BACCM to discuss a proposed change. Which set contains all six core concepts in the model?","opts":["Change, need, solution, value, stakeholder, and context","Scope, cost, schedule, quality, risk, and procurement","Strategy, process, data, technology, people, and governance","Problem, requirement, design, product, test, and release"],"answer":[0],"why":["Correct. The BACCM consists of change, need, solution, value, stakeholder, and context; the concepts are interrelated.","These are project management topics, not the six BACCM concepts.","These may be useful enterprise considerations, but they are not the six named concepts.","These are common delivery artifacts or activities, not the BACCM set."],"ref":"Chapter 2, §§2.1–2.2, p. 5","multi":false,"sourceSet":"ecba-20-untimed-practice.html"},{"id":"q325","domains":[8],"level":3,"tag":"Value","q":"Two solution options are being compared. One raises revenue; the other reduces employee frustration and reputational risk. How does the Standard characterize value?","opts":["Only as a directly measurable financial return","As worth, importance, or usefulness to a stakeholder in context, which may be tangible or intangible","As the total number of requirements delivered","As a fixed amount that is identical for every stakeholder"],"answer":[1],"why":["Financial return can be tangible value, but value is not limited to monetary measures.","Correct. Value is defined in relation to stakeholders and context, and it can be tangible or intangible, realized or preserved.","Requirements delivered do not by themselves show the worth or usefulness of the solution.","The Standard describes value in context; different stakeholders can assess options differently."],"ref":"Chapter 2, §2.2, p. 5","multi":false,"sourceSet":"ecba-20-untimed-practice.html"},{"id":"q326","domains":[2],"level":1,"tag":"Mindset","q":"A business analyst joins an initiative with uncertain needs and unfamiliar stakeholders. Which mindset is most consistent with the Standard?","opts":["Use the same analysis method regardless of context","Stay open and adapt the approach, techniques, and tools to the situation","Wait until every detail is known before engaging stakeholders","Focus only on producing documentation"],"answer":[1],"why":["The Standard says there is no single analysis approach and combinations of techniques depend on context.","Correct. An effective mindset is flexible and adaptable, focused on outcomes, stakeholder value, and learning.","Business analysis can help clarify uncertainty by engaging stakeholders and learning as work proceeds.","Documentation can help, but the mindset also emphasizes outcomes, value, collaboration, and adaptation."],"ref":"Chapter 3, §§3.1–3.2, p. 9","multi":false,"sourceSet":"ecba-20-untimed-practice.html"},{"id":"q327","domains":[7],"level":2,"tag":"Business analysis principles","q":"A team is asked to improve one step in a process. The analyst maps how the process, customers, stakeholders, and desired outcomes connect before recommending a local change. Which principle is being applied?","opts":["See the whole","Avoid waste","Get real using examples","Understand what is doable"],"answer":[0],"why":["Correct. Seeing the whole means considering needs in the big-picture context, including the solution and stakeholders.","Avoiding waste can improve efficiency, but the scenario emphasizes understanding the wider context and relationships.","Examples help build shared understanding, but no specific examples are central to this situation.","Feasibility matters, but the key action is examining the system as a whole."],"ref":"Chapter 3, §3.3, pp. 10–11","multi":false,"sourceSet":"ecba-20-untimed-practice.html"},{"id":"q328","domains":[8],"level":3,"tag":"Foundational competencies","q":"A change affects several connected business units. The analyst looks beyond the immediate team to understand enterprise relationships and how value could be maximized across the whole organization. Which competency is most directly demonstrated?","opts":["Systems thinking","Facilitation","Adaptability","Leadership and influencing"],"answer":[0],"why":["Correct. Systems thinking involves understanding the enterprise and context holistically to maximize delivered value.","Facilitation helps groups work together, but the described capability is holistic enterprise understanding.","Adaptability means adjusting behavioural style to improve effectiveness; it is not the primary competency in this example.","Leadership and influencing helps guide stakeholders and build consensus, but the focus here is interrelationships across the enterprise."],"ref":"Chapter 3, §3.4, p. 12","multi":false,"sourceSet":"ecba-20-untimed-practice.html"},{"id":"q329","domains":[],"level":1,"tag":"Approaches to work","q":"A product team plans short increments, prioritizes the most valuable work, and gathers customer feedback after each increment. Which approach best matches this description?","opts":["Predictive","Adaptive","Hybrid","Sequential"],"answer":[1],"why":["Predictive approaches plan work up front and track progress against that plan.","Correct. Adaptive approaches deliver value in prioritized increments and use stakeholder feedback to learn and adjust.","Hybrid combines predictive and adaptive approaches across an organization or within parts of an initiative; that combination is not described here.","Sequential is not one of the three approaches named in the Standard."],"ref":"Chapter 4, §4.2, pp. 13–14","multi":false,"sourceSet":"ecba-20-untimed-practice.html"},{"id":"q330","domains":[7],"level":2,"tag":"Requirements and designs","q":"A stakeholder states, “We need to see six months of sales data across departments.” The analyst then sketches a dashboard layout. How should these be understood?","opts":["Both are designs because they relate to a dashboard","The sales-data statement is a requirement; the dashboard sketch is a design","The sales-data statement is a design; the sketch is a requirement","Both are requirements because they came from a stakeholder"],"answer":[1],"why":["The statement represents a need, while the sketch represents a potential solution; they serve different purposes.","Correct. Requirements represent needs and what value could be delivered; designs represent solutions and how value might be realized.","This reverses the distinction: the need is the requirement and the proposed dashboard is the design.","The source does not determine the type; the content and purpose do."],"ref":"Chapter 4, §4.4.1, p. 16","multi":false,"sourceSet":"ecba-20-untimed-practice.html"},{"id":"q331","domains":[4],"level":2,"tag":"Requirement classification","q":"A team needs data conversion and staff training to move from its current system to a replacement. Which requirement type best describes these temporary transition needs?","opts":["Business requirements","Stakeholder requirements","Solution requirements","Transition requirements"],"answer":[3],"why":["Business requirements express the goals, objectives, or outcomes that motivate the change.","Stakeholder requirements describe stakeholder needs that must be met to satisfy business requirements.","Solution requirements describe solution capabilities or qualities, rather than temporary needs that enable the move between states.","Correct. Transition requirements are temporary capabilities or conditions needed to move from the current to the future state, such as conversion and training."],"ref":"Chapter 4, §4.4.2, p. 17","multi":false,"sourceSet":"ecba-20-untimed-practice.html"},{"id":"q332","domains":[4],"level":3,"tag":"Traceability","q":"A regulation changes one requirement. The team needs to identify its originating business need, related requirements, and solution components that may be affected. Which practice best supports this analysis?","opts":["Trace requirements and designs","Validate requirements and designs","Prioritize requirements and designs","Measure solution performance"],"answer":[0],"why":["Correct. Traceability links needs, requirements, designs, and solution components, helping identify relationships and assess change impacts.","Validation checks alignment with business objectives and value; it does not primarily map lineage and impact relationships.","Prioritization ranks importance, but does not identify all connected items and downstream effects.","Performance measurement evaluates solution results rather than tracing requirement relationships."],"ref":"Chapter 4, §4.4.3, p. 18","multi":false,"sourceSet":"ecba-20-untimed-practice.html"}]);